(169, 'default', '{\"uuid\":\"4ed792f1-7cc6-48dd-9d2f-b8f6c224bdca\",\"displayName\":\"App\\\\Jobs\\\\ImportAnimeJob\",\"job\":\"Illuminate\\\\Queue\\\\CallQueuedHandler@call\",\"maxTries\":3,\"maxExceptions\":null,\"failOnTimeout\":false,\"backoff\":null,\"timeout\":120,\"retryUntil\":null,\"data\":{\"commandName\":\"App\\\\Jobs\\\\ImportAnimeJob\",\"command\":\"O:23:\\\"App\\\\Jobs\\\\ImportAnimeJob\\\":2:{s:9:\\\"animeData\\\";a:21:{s:6:\\\"mal_id\\\";i:52;s:5:\\\"title\\\";s:25:\\\"Battle Doll Angelic Layer\\\";s:14:\\\"title_japanese\\\";s:45:\\\"機動天使エンジェリックレイヤー\\\";s:4:\\\"slug\\\";N;s:11:\\\"description\\\";s:294:\\\"12-year-old Misaki Suzuhara has just gotten involved in Angelic Layer, a battling game using electronic dolls called angels. Even as a newbie, Misaki shows advanced skills as she meets new friends and enters Angelic Layer tournaments to fight the greatest Angelic Layer champions of the nation.\\\";s:4:\\\"type\\\";s:2:\\\"TV\\\";s:6:\\\"status\\\";s:9:\\\"Completed\\\";s:7:\\\"country\\\";s:2:\\\"JP\\\";s:6:\\\"season\\\";s:6:\\\"Spring\\\";s:4:\\\"year\\\";i:2001;s:6:\\\"rating\\\";s:25:\\\"PG-13 - Teens 13 or older\\\";s:5:\\\"score\\\";d:7.3;s:14:\\\"episodes_count\\\";i:26;s:8:\\\"duration\\\";i:24;s:6:\\\"source\\\";s:5:\\\"Manga\\\";s:6:\\\"studio\\\";s:5:\\\"Bones\\\";s:9:\\\"producers\\\";s:22:\\\"Dentsu, TV Tokyo Music\\\";s:9:\\\"licensors\\\";s:27:\\\"ADV Films, Sentai Filmworks\\\";s:9:\\\"thumbnail\\\";s:53:\\\"https:\\/\\/myanimelist.net\\/images\\/anime\\/1192\\/113699l.jpg\\\";s:6:\\\"banner\\\";s:53:\\\"https:\\/\\/myanimelist.net\\/images\\/anime\\/1192\\/113699l.jpg\\\";s:6:\\\"genres\\\";a:4:{i:0;a:2:{s:6:\\\"mal_id\\\";i:46;s:4:\\\"name\\\";s:13:\\\"Award Winning\\\";}i:1;a:2:{s:6:\\\"mal_id\\\";i:4;s:4:\\\"name\\\";s:6:\\\"Comedy\\\";}i:2;a:2:{s:6:\\\"mal_id\\\";i:8;s:4:\\\"name\\\";s:5:\\\"Drama\\\";}i:3;a:2:{s:6:\\\"mal_id\\\";i:24;s:4:\\\"name\\\";s:6:\\\"Sci-Fi\\\";}}}s:13:\\\"fetchEpisodes\\\";b:0;}\"}}', 0, NULL, 1779080691, 1779080691),
(170, 'default', '{\"uuid\":\"18cff2d8-0b32-49da-a068-82ec4e3de97b\",\"displayName\":\"App\\\\Jobs\\\\ImportAnimeJob\",\"job\":\"Illuminate\\\\Queue\\\\CallQueuedHandler@call\",\"maxTries\":3,\"maxExceptions\":null,\"failOnTimeout\":false,\"backoff\":null,\"timeout\":120,\"retryUntil\":null,\"data\":{\"commandName\":\"App\\\\Jobs\\\\ImportAnimeJob\",\"command\":\"O:23:\\\"App\\\\Jobs\\\\ImportAnimeJob\\\":2:{s:9:\\\"animeData\\\";a:21:{s:6:\\\"mal_id\\\";i:53;s:5:\\\"title\\\";s:13:\\\"Ai Yori Aoshi\\\";s:14:\\\"title_japanese\\\";s:15:\\\"藍より青し\\\";s:4:\\\"slug\\\";N;s:11:\\\"description\\\";s:822:\\\"Kaoru Hanabishi, a college student who lives alone, met a beautiful but bewildered girl dressed in a kimono at a train station. He volunteered to guide her way to the address she was looking for, which happened to be in his neighborhood, but turned out to be an empty lot. Not knowing what to do next, Kaoru invited the devastated girl to his apartment and asked for any additional clues to her destination. She supplied him with a photo of two children whom Kaoru immediately identified as himself and Aoi Sakuraba, his childhood friend. It turned out that the girl in front of him is Aoi Sakuraba herself, his betrothed fiancee who came all the way to Tokyo to marry him. Her revelation was not only surprising but also reminded the deepest part of Kaoru\'s memory for why he left the Hanabishi family in the first place.\\\";s:4:\\\"type\\\";s:2:\\\"TV\\\";s:6:\\\"status\\\";s:9:\\\"Completed\\\";s:7:\\\"country\\\";s:2:\\\"JP\\\";s:6:\\\"season\\\";s:6:\\\"Spring\\\";s:4:\\\"year\\\";i:2002;s:6:\\\"rating\\\";s:25:\\\"PG-13 - Teens 13 or older\\\";s:5:\\\"score\\\";d:7.12;s:14:\\\"episodes_count\\\";i:24;s:8:\\\"duration\\\";i:23;s:6:\\\"source\\\";s:5:\\\"Manga\\\";s:6:\\\"studio\\\";s:9:\\\"J.C.Staff\\\";s:9:\\\"producers\\\";s:39:\\\"Movic, Fuji TV, Pioneer LDC, Cosmic Ray\\\";s:9:\\\"licensors\\\";s:36:\\\"Funimation, Geneon Entertainment USA\\\";s:9:\\\"thumbnail\\\";s:53:\\\"https:\\/\\/myanimelist.net\\/images\\/anime\\/1311\\/154076l.jpg\\\";s:6:\\\"banner\\\";s:53:\\\"https:\\/\\/myanimelist.net\\/images\\/anime\\/1311\\/154076l.jpg\\\";s:6:\\\"genres\\\";a:3:{i:0;a:2:{s:6:\\\"mal_id\\\";i:4;s:4:\\\"name\\\";s:6:\\\"Comedy\\\";}i:1;a:2:{s:6:\\\"mal_id\\\";i:8;s:4:\\\"name\\\";s:5:\\\"Drama\\\";}i:2;a:2:{s:6:\\\"mal_id\\\";i:22;s:4:\\\"name\\\";s:7:\\\"Romance\\\";}}}s:13:\\\"fetchEpisodes\\\";b:0;}\"}}', 0, NULL, 1779080691, 1779080691),
(171, 'default', '{\"uuid\":\"911e5ae1-73ab-48a0-8a79-f0c18109533c\",\"displayName\":\"App\\\\Jobs\\\\ImportAnimeJob\",\"job\":\"Illuminate\\\\Queue\\\\CallQueuedHandler@call\",\"maxTries\":3,\"maxExceptions\":null,\"failOnTimeout\":false,\"backoff\":null,\"timeout\":120,\"retryUntil\":null,\"data\":{\"commandName\":\"App\\\\Jobs\\\\ImportAnimeJob\",\"command\":\"O:23:\\\"App\\\\Jobs\\\\ImportAnimeJob\\\":2:{s:9:\\\"animeData\\\";a:21:{s:6:\\\"mal_id\\\";i:54;s:5:\\\"title\\\";s:17:\\\"Appleseed (Movie)\\\";s:14:\\\"title_japanese\\\";s:21:\\\"アップルシード\\\";s:4:\\\"slug\\\";N;s:11:\\\"description\\\";s:754:\\\"With Earth seemingly entangled in endless war, it is hard to believe that the city of Olympus has attained a utopian society. This peaceful haven is made possible through its population made up predominantly of Bioroids—genetically engineered humans who can no longer reproduce on their own or experience extreme emotions.\\n\\nDeunan Knute is a legendary soldier who has been fighting in the wastelands for as long as she can remember. When Hitomi, a representative of Olympus, scouts her to become a part of their security force, Deunan is skeptical that there can truly be a place so calm. Proving her suspicions correct, Deunan soon learns of a dangerous plot that promises to plunge the city into chaos—by threatening the very existence of Bioroids.\\\";s:4:\\\"type\\\";s:5:\\\"Movie\\\";s:6:\\\"status\\\";s:9:\\\"Completed\\\";s:7:\\\"country\\\";s:2:\\\"JP\\\";s:6:\\\"season\\\";N;s:4:\\\"year\\\";N;s:6:\\\"rating\\\";s:30:\\\"R - 17+ (violence & profanity)\\\";s:5:\\\"score\\\";d:7.05;s:14:\\\"episodes_count\\\";i:1;s:8:\\\"duration\\\";i:45;s:6:\\\"source\\\";s:5:\\\"Manga\\\";s:6:\\\"studio\\\";s:16:\\\"Digital Frontier\\\";s:9:\\\"producers\\\";s:77:\\\"Mainichi Broadcasting System, TOHO, TYO Animations, TYO, Geneon Entertainment\\\";s:9:\\\"licensors\\\";s:42:\\\"Sentai Filmworks, Geneon Entertainment USA\\\";s:9:\\\"thumbnail\\\";s:49:\\\"https:\\/\\/myanimelist.net\\/images\\/anime\\/9\\/57231l.jpg\\\";s:6:\\\"banner\\\";s:49:\\\"https:\\/\\/myanimelist.net\\/images\\/anime\\/9\\/57231l.jpg\\\";s:6:\\\"genres\\\";a:1:{i:0;a:2:{s:6:\\\"mal_id\\\";i:24;s:4:\\\"name\\\";s:6:\\\"Sci-Fi\\\";}}}s:13:\\\"fetchEpisodes\\\";b:0;}\"}}', 0, NULL, 1779080691, 1779080691),
(172, 'default', '{\"uuid\":\"f927f567-9bde-48c4-b9d2-49765f1a243e\",\"displayName\":\"App\\\\Jobs\\\\ImportAnimeJob\",\"job\":\"Illuminate\\\\Queue\\\\CallQueuedHandler@call\",\"maxTries\":3,\"maxExceptions\":null,\"failOnTimeout\":false,\"backoff\":null,\"timeout\":120,\"retryUntil\":null,\"data\":{\"commandName\":\"App\\\\Jobs\\\\ImportAnimeJob\",\"command\":\"O:23:\\\"App\\\\Jobs\\\\ImportAnimeJob\\\":2:{s:9:\\\"animeData\\\";a:21:{s:6:\\\"mal_id\\\";i:55;s:5:\\\"title\\\";s:11:\\\"Arc the Lad\\\";s:14:\\\"title_japanese\\\";s:21:\\\"アークザラッド\\\";s:4:\\\"slug\\\";N;s:11:\\\"description\\\";s:479:\\\"The story follows Elk, a bounty hunter in some strange futuristic world. On this world archaic but advanced technology exists side by side with primitive attitudes, beasts and magic. In other words it\'s got a bit of everything. It also has an evil conspiracy who are able to produce powerful monsters called chimera, who can also appear as human. Naturally it is not long before Elk has rescued a young female beast-master and gained himself some serious enemies. \\n\\n(Source: ANN)\\\";s:4:\\\"type\\\";s:2:\\\"TV\\\";s:6:\\\"status\\\";s:9:\\\"Completed\\\";s:7:\\\"country\\\";s:2:\\\"JP\\\";s:6:\\\"season\\\";s:6:\\\"Spring\\\";s:4:\\\"year\\\";i:1999;s:6:\\\"rating\\\";s:30:\\\"R - 17+ (violence & profanity)\\\";s:5:\\\"score\\\";d:6.66;s:14:\\\"episodes_count\\\";i:26;s:8:\\\"duration\\\";i:22;s:6:\\\"source\\\";s:4:\\\"Game\\\";s:6:\\\"studio\\\";s:9:\\\"Bee Train\\\";s:9:\\\"producers\\\";s:68:\\\"Sony Pictures Entertainment, Aniplex, Sony Interactive Entertainment\\\";s:9:\\\"licensors\\\";s:9:\\\"ADV Films\\\";s:9:\\\"thumbnail\\\";s:49:\\\"https:\\/\\/myanimelist.net\\/images\\/anime\\/3\\/49041l.jpg\\\";s:6:\\\"banner\\\";s:49:\\\"https:\\/\\/myanimelist.net\\/images\\/anime\\/3\\/49041l.jpg\\\";s:6:\\\"genres\\\";a:5:{i:0;a:2:{s:6:\\\"mal_id\\\";i:1;s:4:\\\"name\\\";s:6:\\\"Action\\\";}i:1;a:2:{s:6:\\\"mal_id\\\";i:2;s:4:\\\"name\\\";s:9:\\\"Adventure\\\";}i:2;a:2:{s:6:\\\"mal_id\\\";i:10;s:4:\\\"name\\\";s:7:\\\"Fantasy\\\";}i:3;a:2:{s:6:\\\"mal_id\\\";i:14;s:4:\\\"name\\\";s:6:\\\"Horror\\\";}i:4;a:2:{s:6:\\\"mal_id\\\";i:24;s:4:\\\"name\\\";s:6:\\\"Sci-Fi\\\";}}}s:13:\\\"fetchEpisodes\\\";b:0;}\"}}', 0, NULL, 1779080691, 1779080691),
(173, 'default', '{\"uuid\":\"0da788d8-5bed-4bf2-b2a6-29df2f569f23\",\"displayName\":\"App\\\\Jobs\\\\ImportAnimeJob\",\"job\":\"Illuminate\\\\Queue\\\\CallQueuedHandler@call\",\"maxTries\":3,\"maxExceptions\":null,\"failOnTimeout\":false,\"backoff\":null,\"timeout\":120,\"retryUntil\":null,\"data\":{\"commandName\":\"App\\\\Jobs\\\\ImportAnimeJob\",\"command\":\"O:23:\\\"App\\\\Jobs\\\\ImportAnimeJob\\\":2:{s:9:\\\"animeData\\\";a:21:{s:6:\\\"mal_id\\\";i:56;s:5:\\\"title\\\";s:7:\\\"Avenger\\\";s:14:\\\"title_japanese\\\";s:21:\\\"アヴェンジャー\\\";s:4:\\\"slug\\\";N;s:11:\\\"description\\\";s:463:\\\"Mars has been colonized and is a world where children have been replaced by robot servants known as \\\"dolls.\\\" Layla is a skilled fighter with a tragic past who travels about the world. Her companions are Nei, a strange and unique doll with some unknown ties to Layla, and Speedy, who is a doll breeder. The founders of Mars see the trio as a threat to their world, and each time they attack Layla and Nei a bit more of their mysterious past and future is revealed.\\\";s:4:\\\"type\\\";s:2:\\\"TV\\\";s:6:\\\"status\\\";s:9:\\\"Completed\\\";s:7:\\\"country\\\";s:2:\\\"JP\\\";s:6:\\\"season\\\";s:4:\\\"Fall\\\";s:4:\\\"year\\\";i:2003;s:6:\\\"rating\\\";s:30:\\\"R - 17+ (violence & profanity)\\\";s:5:\\\"score\\\";d:5.96;s:14:\\\"episodes_count\\\";i:13;s:8:\\\"duration\\\";i:23;s:6:\\\"source\\\";s:8:\\\"Original\\\";s:6:\\\"studio\\\";s:9:\\\"Bee Train\\\";s:9:\\\"producers\\\";s:18:\\\"Yomiko Advertising\\\";s:9:\\\"licensors\\\";s:20:\\\"Bandai Entertainment\\\";s:9:\\\"thumbnail\\\";s:53:\\\"https:\\/\\/myanimelist.net\\/images\\/anime\\/1112\\/154871l.jpg\\\";s:6:\\\"banner\\\";s:53:\\\"https:\\/\\/myanimelist.net\\/images\\/anime\\/1112\\/154871l.jpg\\\";s:6:\\\"genres\\\";a:3:{i:0;a:2:{s:6:\\\"mal_id\\\";i:2;s:4:\\\"name\\\";s:9:\\\"Adventure\\\";}i:1;a:2:{s:6:\\\"mal_id\\\";i:10;s:4:\\\"name\\\";s:7:\\\"Fantasy\\\";}i:2;a:2:{s:6:\\\"mal_id\\\";i:24;s:4:\\\"name\\\";s:6:\\\"Sci-Fi\\\";}}}s:13:\\\"fetchEpisodes\\\";b:0;}\"}}', 0, NULL, 1779080691, 1779080691);
